        for (y, row) in level.split('\n').enumerate().take(H - 1) {
            for (x, ch) in row.bytes().enumerate().take(W) {
                grid[y][x] = ch;
                orig[y][x] = match ch {
                    b'1' => 1,
                    b'2' => 2,
                    b'3' => 3,
