            grid,
            orig,
            px: (W - PADDLE) / 2,
            pw: PADDLE,
            bx: 0,
            by: 0,
            vx: 1,
            vy: -1,
            score: 0,
            lives: LIVES,
            destroyed: 0,
            state: State::Playing,
